insert into public.salas (id, slug, titulo, tipo, descricao, bairro, capacidade, tomadas, mesas, preco_centavos, fotos)
values
    ('00000000-0000-4000-8000-000000000001', 'sala-aurora', 'Sala Aurora', 'privativa', 'Espaço de trabalho compartilhado com mesa individual, cadeira ergonômica, Wi-Fi de alta velocidade e ar-condicionado. Ideal para quem busca produtividade e conforto.', 'Centro', 4, 4, 1, 7000, array['escritorio1.jpg']),
    ('00000000-0000-4000-8000-000000000002', 'hub-colmeia', 'Hub Colmeia', 'compartilhada', 'Estação de trabalho compartilhada em ambiente colaborativo, com internet de alta velocidade e climatização. Perfeita para freelancers e profissionais que buscam networking.', 'Rocho', 5, 2, 1, 6000, array['escritorio2.jpg']),
    ('00000000-0000-4000-8000-000000000003', 'sala-bussola', 'Sala Bússola', 'reuniao', 'Sala de reunião ampla e equipada, ideal para apresentações, treinamentos e encontros corporativos. Conta com projetor, quadro branco e Wi-Fi dedicado.', 'Vila Yamada', 10, 8, 1, 22000, array['escritorio3.jpg']),
    ('00000000-0000-4000-8000-000000000004', 'estudio-nomade', 'Estúdio Nômade', 'estudio', 'Estúdio versátil pensado para equipes criativas, com iluminação natural, espaço para brainstorm e mobiliário flexível.', 'Vila Xavier', 6, 6, 3, 15000, array['escritorio4.jpg']),
    ('00000000-0000-4000-8000-000000000005', 'sala-farol', 'Sala Farol', 'privativa', 'Sala privativa e silenciosa, perfeita para reuniões confidenciais ou trabalho em dupla, com decoração aconchegante e boa iluminação.', 'Imperador', 2, 4, 2, 13000, array['escritorio5.jpg']),
    ('00000000-0000-4000-8000-000000000006', 'coworking-ponto', 'Coworking Ponto', 'compartilhada', 'Estação compartilhada no coração do Centro, com fácil acesso a transporte público e cafeteria no local.', 'Centro', 7, 2, 1, 4500, array['escritorio6.jpg']),
    ('00000000-0000-4000-8000-000000000007', 'sala-orbita', 'Sala Órbita', 'reuniao', 'Sala de reunião moderna com equipamento de videoconferência, ideal para reuniões híbridas e apresentações para clientes.', 'Maria Luiza', 8, 6, 1, 19000, array['escritorio7.jpg']),
    ('00000000-0000-4000-8000-000000000008', 'atelie-vento', 'Ateliê Vento', 'estudio', 'Ateliê espaçoso e bem ventilado, com ambiente inspirador para trabalhos manuais, design e produção de conteúdo.', 'Indaiá', 5, 5, 2, 17000, array['escritorio8.jpg']);
